ALTER TABLE app_users ADD CONSTRAINT approvals_roles CHECK(role IN ('owner','employee','approver','finance','member'));
CREATE TABLE approval_types(id uuid PRIMARY KEY,name text NOT NULL UNIQUE CHECK(length(name) BETWEEN 1 AND 80),kind text NOT NULL CHECK(kind IN ('expense','purchase','leave')));
INSERT INTO approval_types VALUES ('10000000-0000-4000-8000-000000000001','Expense','expense'),('10000000-0000-4000-8000-000000000002','Purchase','purchase'),('10000000-0000-4000-8000-000000000003','Leave','leave');
CREATE TABLE approval_fields(id uuid PRIMARY KEY,type_id uuid NOT NULL REFERENCES approval_types(id),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 80),required boolean NOT NULL DEFAULT false,UNIQUE(type_id,name),UNIQUE(id,type_id));
INSERT INTO approval_fields VALUES('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Business purpose',true),('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','Supplier',true),('20000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000003','Leave note',false);
CREATE TABLE approval_categories(id uuid PRIMARY KEY,name text NOT NULL UNIQUE CHECK(length(name) BETWEEN 1 AND 80));
INSERT INTO approval_categories VALUES('30000000-0000-4000-8000-000000000001','General'),('30000000-0000-4000-8000-000000000002','Travel');
CREATE TABLE approval_statuses(id uuid PRIMARY KEY,name text NOT NULL UNIQUE CHECK(length(name) BETWEEN 1 AND 80),phase text NOT NULL CHECK(phase IN ('draft','pending','changes','approved','rejected','paid')),UNIQUE(id,phase));
INSERT INTO approval_statuses VALUES('40000000-0000-4000-8000-000000000001','Draft','draft'),('40000000-0000-4000-8000-000000000002','Awaiting approval','pending'),('40000000-0000-4000-8000-000000000003','Changes requested','changes'),('40000000-0000-4000-8000-000000000004','Approved','approved'),('40000000-0000-4000-8000-000000000005','Rejected','rejected'),('40000000-0000-4000-8000-000000000006','Paid','paid');
CREATE TABLE approval_rules(type_id uuid PRIMARY KEY REFERENCES approval_types(id),threshold bigint NOT NULL CHECK(threshold BETWEEN 0 AND 1000000000),first_id uuid NOT NULL REFERENCES app_users(id),second_id uuid REFERENCES app_users(id),CHECK(first_id IS DISTINCT FROM second_id));
CREATE TABLE approval_requests(id uuid PRIMARY KEY,type_id uuid NOT NULL REFERENCES approval_types(id),submitter_id uuid NOT NULL REFERENCES app_users(id),title text NOT NULL CHECK(length(title) BETWEEN 1 AND 160),status_id uuid NOT NULL,phase text NOT NULL DEFAULT 'draft',round integer NOT NULL DEFAULT 0,leave_year integer CHECK(leave_year BETWEEN 2000 AND 2200),leave_days integer CHECK(leave_days BETWEEN 1 AND 366),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(status_id,phase) REFERENCES approval_statuses(id,phase),UNIQUE(id,type_id));
CREATE INDEX approval_requests_submitter ON approval_requests(submitter_id);
CREATE TABLE approval_values(request_id uuid NOT NULL,type_id uuid NOT NULL,field_id uuid NOT NULL,value text NOT NULL CHECK(length(value)<=2000),PRIMARY KEY(request_id,field_id),FOREIGN KEY(request_id,type_id) REFERENCES approval_requests(id,type_id),FOREIGN KEY(field_id,type_id) REFERENCES approval_fields(id,type_id));
CREATE TABLE approval_lines(id uuid PRIMARY KEY,request_id uuid NOT NULL REFERENCES approval_requests(id),amount integer NOT NULL CHECK(amount BETWEEN 0 AND 100000000),category_id uuid NOT NULL REFERENCES approval_categories(id),spent_on date NOT NULL);
CREATE TABLE approval_receipts(id uuid PRIMARY KEY,request_id uuid NOT NULL REFERENCES approval_requests(id),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE approval_steps(id uuid PRIMARY KEY,request_id uuid NOT NULL REFERENCES approval_requests(id),round integer NOT NULL,position integer NOT NULL CHECK(position IN (1,2)),approver_id uuid NOT NULL REFERENCES app_users(id),decision text CHECK(decision IN ('approve','reject','changes')),reason text,decided_at timestamptz,UNIQUE(request_id,round,position),UNIQUE(request_id,round,approver_id));
CREATE INDEX approval_steps_approver ON approval_steps(approver_id,request_id);
CREATE TABLE approval_comments(id uuid PRIMARY KEY,request_id uuid NOT NULL REFERENCES approval_requests(id),user_id uuid NOT NULL REFERENCES app_users(id),body text NOT NULL CHECK(length(body) BETWEEN 1 AND 4000),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE approval_audit(id uuid PRIMARY KEY,request_id uuid NOT NULL REFERENCES approval_requests(id),actor_id uuid NOT NULL REFERENCES app_users(id),event text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE approval_balances(user_id uuid NOT NULL REFERENCES app_users(id),year integer NOT NULL CHECK(year BETWEEN 2000 AND 2200),days integer NOT NULL CHECK(days BETWEEN 0 AND 366),PRIMARY KEY(user_id,year));
CREATE TABLE approvals_invites(id uuid PRIMARY KEY,token_hash text NOT NULL UNIQUE,email text NOT NULL,role text NOT NULL CHECK(role IN ('employee','approver','finance')),invited_by uuid NOT NULL REFERENCES app_users(id),expires_at timestamptz NOT NULL,used_at timestamptz,emailed boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX approvals_invites_active ON approvals_invites(email) WHERE used_at IS NULL;
CREATE TABLE approval_mail(id uuid PRIMARY KEY,request_id uuid NOT NULL REFERENCES approval_requests(id),dedupe text NOT NULL UNIQUE,recipient text NOT NULL,subject text NOT NULL,body text NOT NULL,delivery text NOT NULL DEFAULT 'not-sent');
